import { z } from "zod";
export const partSchema = z.object({ unitId:z.string().uuid(), partName:z.string().trim().min(1).max(120), costCentavos:z.number().int().nonnegative(), replacedOn:z.string(), replacementMileage:z.number().int().nonnegative().optional(), nextDueDate:z.string().optional(), nextDueMileage:z.number().int().nonnegative().optional(), notes:z.string().max(1000).optional() }).refine((v)=>Boolean(v.nextDueDate||v.nextDueMileage),"Add a date or mileage due value");
export const tireSchema = z.object({ unitId:z.string().uuid(), position:z.enum(["front","rear_left","rear_right"]), brand:z.string().trim().min(1).max(80), installedOn:z.string(), installedMileage:z.number().int().nonnegative().optional(), costCentavos:z.number().int().nonnegative(), nextDueDate:z.string().optional(), nextDueMileage:z.number().int().nonnegative().optional() }).refine((v)=>Boolean(v.nextDueDate||v.nextDueMileage),"Add a date or mileage due value");
